import zipfile
path = '/root/project_proposal_ready.hwpx'
with zipfile.ZipFile(path, 'r') as z:
    print('Valid ZIP:', z.testzip() is None)
    for name in z.namelist():
        data = z.read(name)
        try:
            text = data.decode('utf-8')
            if '{{' in text:
                print(f'ERROR: placeholder remaining in {name}')
            if '개월' in text:
                for line in text.split('\n'):
                    if '개월' in line:
                        print(f'Month span found in {name}: {line[:300]}')
            # Check budget normalization
            if '₩450000000' in text:
                print(f'Budget correctly normalized in {name}')
            elif '₩450,000,000' in text:
                print(f'ERROR: Budget still has commas in {name}')
        except:
            pass
    # Check mimetype
    try:
        info = z.getinfo('mimetype')
        print('mimetype compress_type:', info.compress_type, '(should be 0)')
    except KeyError:
        print('No mimetype entry found')
print('Output file exists and is valid.')
"

