python3 -c "
import zipfile
import re

path = '/root/project_proposal_ready.hwpx'
print('=' * 60)
print('FINAL VERIFICATION')
print('=' * 60)

with zipfile.ZipFile(path, 'r') as z:
    print(f'Valid ZIP: {z.testzip() is None}')
    print(f'Entries: {z.namelist()}')
    print()

    all_ok = True

    for name in z.namelist():
        data = z.read(name)
        try:
            text = data.decode('utf-8')

            # Check for remaining placeholders
            if '{{' in text:
                print(f'ERROR: Placeholder remaining in {name}')
                all_ok = False

            # Check budget normalization
            if '예산' in text:
                if '₩450000000' in text:
                    print(f'✓ Budget normalized correctly: ₩450000000')
                elif '₩450,000,000' in text:
                    print(f'ERROR: Budget still has commas')
                    all_ok = False

            # Check month spans
            if '단계' in text:
                for i, line in enumerate(text.split('\n')):
                    if '단계' in line:
                        # Extract the text content
                        match = re.search(r'<hp:t>(.*?)</hp:t>', line)
                        if match:
                            content = match.group(1)
                            print(f'✓ Phase line: {content}')

            # Check linesegarray removal from modified paragraphs
            if '<hp:p' in text:
                for para_match in re.finditer(r'(<hp:p[^>]*>)(.*?)(</hp:p>)', text, re.DOTALL):
                    para_content = para_match.group(2)
                    # Check if this paragraph was modified (has our data)
                    if any(x in para_content for x in ['스마트 워크플로우', '디지털 혁신실', '₩450000000', '3개월', '1개월', '최수민 차장']):
                        if '<hp:linesegarray' in para_content.lower():
                            print(f'ERROR: linesegarray not removed from modified paragraph')
                            all_ok = False
                        else:
                            # Get first text snippet
                            text_match = re.search(r'<hp:t>([^<]{5,30})', para_content)
                            if text_match:
                                print(f'✓ linesegarray removed from: {text_match.group(1)}...')

        except UnicodeDecodeError:
            pass

    print()
    if all_ok:
        print('✓ ALL CHECKS PASSED')
    else:
        print('✗ SOME CHECKS FAILED')
"

